// 3D room builder. floorTiles is shared with the 2D plan and local save data.
const builderCanvas=$('builder3dCanvas'),builderCtx=builderCanvas.getContext('2d');
let buildTool='add',buildRotation=0,wallHeightCm=240,buildHover=null,isoUnit=30;
const buildPalette={floor:'#d8bf96',floorSide:'#9d8061',wall:'#eee9df',wallSide:'#c7beb0',edge:'#756d62'};
function tileKey(x,y,size){return`${x}:${y}:${size}`}
function normalizedTiles(){const size=gridPx();return floorTiles.filter(t=>t.size===size).map(t=>({...t,gx:Math.round(t.x/size),gy:Math.round(t.y/size)}))}
function buildBounds(tiles){if(!tiles.length)return{minX:-3,maxX:3,minY:-3,maxY:3};return{minX:Math.min(...tiles.map(t=>t.gx))-2,maxX:Math.max(...tiles.map(t=>t.gx))+2,minY:Math.min(...tiles.map(t=>t.gy))-2,maxY:Math.max(...tiles.map(t=>t.gy))+2}}
function rotateGrid(x,y){for(let n=0;n<buildRotation;n++)[x,y]=[-y,x];return[x,y]}
function fitBuilder(tiles){const b=buildBounds(tiles),sum=b.maxX-b.minX+b.maxY-b.minY+2;isoUnit=Math.max(7,Math.min(34,(builderCanvas.width-90)/(sum+1),(builderCanvas.height-250)*2/(sum+1)));return b}
function isoPoint(gx,gy,z,bounds){const cx=(bounds.minX+bounds.maxX+1)/2,cy=(bounds.minY+bounds.maxY+1)/2,[rx,ry]=rotateGrid(gx-cx,gy-cy);return[builderCanvas.width/2+(rx-ry)*isoUnit,builderCanvas.height*.56+(rx+ry)*isoUnit/2-z]}
function polygon(points,fill,stroke=buildPalette.edge){builderCtx.beginPath();points.forEach((p,n)=>n?builderCtx.lineTo(...p):builderCtx.moveTo(...p));builderCtx.closePath();if(fill){builderCtx.fillStyle=fill;builderCtx.fill()}if(stroke){builderCtx.strokeStyle=stroke;builderCtx.lineWidth=1.2;builderCtx.stroke()}}
function groundCell(gx,gy,bounds,hover){const p=[isoPoint(gx,gy,0,bounds),isoPoint(gx+1,gy,0,bounds),isoPoint(gx+1,gy+1,0,bounds),isoPoint(gx,gy+1,0,bounds)];polygon(p,hover?'#efb557':'rgba(255,255,255,.12)','rgba(91,92,84,.35)')}
function tileFace(gx,gy,color,bounds){const a=isoPoint(gx,gy,0,bounds),b=isoPoint(gx+1,gy,0,bounds),c=isoPoint(gx+1,gy+1,0,bounds),d=isoPoint(gx,gy+1,0,bounds),depth=Math.max(4,isoUnit*.2);polygon([a,b,c,d],color);polygon([d,c,[c[0],c[1]+depth],[d[0],d[1]+depth]],buildPalette.floorSide)}
function wallFace(gx,gy,side,height,bounds){const corners={n:[isoPoint(gx,gy,0,bounds),isoPoint(gx+1,gy,0,bounds)],e:[isoPoint(gx+1,gy,0,bounds),isoPoint(gx+1,gy+1,0,bounds)],s:[isoPoint(gx+1,gy+1,0,bounds),isoPoint(gx,gy+1,0,bounds)],w:[isoPoint(gx,gy+1,0,bounds),isoPoint(gx,gy,0,bounds)]},base=corners[side],top=base.map(p=>[p[0],p[1]-height]);polygon([base[0],base[1],top[1],top[0]],side==='n'||side==='e'?buildPalette.wall:buildPalette.wallSide)}
function drawRoomPartitions(bounds,height,set){const size=gridPx(),seen=new Set();items.filter(i=>i.type==='room'&&Math.abs(i.rotation||0)<1).forEach(room=>{const x0=Math.floor(room.x/size),y0=Math.floor(room.y/size),x1=Math.ceil((room.x+room.w)/size),y1=Math.ceil((room.y+room.h)/size),draw=(x,y,side)=>{const key=`${x}:${y}:${side}`;if(!seen.has(key)&&set.has(`${x}:${y}`)){seen.add(key);wallFace(x,y,side,height,bounds)}};for(let x=x0;x<x1;x++){draw(x,y0,'n');draw(x,y1-1,'s')}for(let y=y0;y<y1;y++){draw(x0,y,'w');draw(x1-1,y,'e')}})}
function drawBuilder(){const w=builderCanvas.width,h=builderCanvas.height,tiles=normalizedTiles(),bounds=fitBuilder(tiles),set=new Set(tiles.map(t=>`${t.gx}:${t.gy}`));builderCtx.clearRect(0,0,w,h);const sky=builderCtx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#b8cfda');sky.addColorStop(.58,'#e9e5dc');sky.addColorStop(1,'#b3a58e');builderCtx.fillStyle=sky;builderCtx.fillRect(0,0,w,h);for(let y=bounds.minY;y<=bounds.maxY;y++)for(let x=bounds.minX;x<=bounds.maxX;x++)groundCell(x,y,bounds,buildHover?.gx===x&&buildHover?.gy===y);tiles.sort((a,b)=>(a.gx+a.gy)-(b.gx+b.gy)).forEach(t=>tileFace(t.gx,t.gy,t.color||buildPalette.floor,bounds));const height=Math.max(55,Math.min(125,wallHeightCm*.42));tiles.forEach(t=>{if(!set.has(`${t.gx}:${t.gy-1}`))wallFace(t.gx,t.gy,'n',height,bounds);if(!set.has(`${t.gx+1}:${t.gy}`))wallFace(t.gx,t.gy,'e',height,bounds);if(!set.has(`${t.gx}:${t.gy+1}`))wallFace(t.gx,t.gy,'s',height,bounds);if(!set.has(`${t.gx-1}:${t.gy}`))wallFace(t.gx,t.gy,'w',height,bounds)});drawRoomPartitions(bounds,height*.92,set);builderCtx.fillStyle='#ffffffdf';builderCtx.font='600 15px sans-serif';builderCtx.fillText(`${floorTiles.length}マス / 壁高 ${wallHeightCm}cm`,20,h-20)}
function resizeBuilder(){const r=$('builder3dModal').getBoundingClientRect(),ratio=Math.min(2,window.devicePixelRatio||1);builderCanvas.width=Math.max(640,Math.round(r.width*ratio));builderCanvas.height=Math.max(540,Math.round(r.height*ratio));drawBuilder()}
function screenToGrid(clientX,clientY){const r=builderCanvas.getBoundingClientRect(),mx=(clientX-r.left)*builderCanvas.width/r.width,my=(clientY-r.top)*builderCanvas.height/r.height,tiles=normalizedTiles(),bounds=fitBuilder(tiles),cx=(bounds.minX+bounds.maxX+1)/2,cy=(bounds.minY+bounds.maxY+1)/2,dx=(mx-builderCanvas.width/2)/isoUnit,dy=(my-builderCanvas.height*.56)/(isoUnit/2);let rx=(dx+dy)/2,ry=(dy-dx)/2;for(let n=0;n<(4-buildRotation)%4;n++)[rx,ry]=[-ry,rx];return{gx:Math.floor(rx+cx),gy:Math.floor(ry+cy)}}
function editBuildCell(gx,gy){const size=gridPx(),x=gx*size,y=gy*size;if(x<0||y<0||x+size>canvas.clientWidth||y+size>canvas.clientHeight)return;const at=floorTiles.findIndex(t=>t.x===x&&t.y===y&&t.size===size);checkpoint();if(buildTool==='remove'){if(at>=0)floorTiles.splice(at,1)}else if(at<0)floorTiles.push({x,y,size,color:floorColor,key:tileKey(x,y,size)});render();scheduleSave();drawBuilder()}
builderCanvas.addEventListener('pointermove',e=>{buildHover=screenToGrid(e.clientX,e.clientY);drawBuilder()});builderCanvas.addEventListener('pointerleave',()=>{buildHover=null;drawBuilder()});builderCanvas.addEventListener('click',e=>{const g=screenToGrid(e.clientX,e.clientY);editBuildCell(g.gx,g.gy)});
$('builder3dBtn').onclick=()=>{$('builder3dModal').classList.remove('hidden');requestAnimationFrame(resizeBuilder)};$('closeBuilder3dBtn').onclick=()=>{$('builder3dModal').classList.add('hidden');render();toast('3D編集を間取り図へ反映しました')};
document.querySelectorAll('[data-build-tool]').forEach(b=>b.onclick=()=>{buildTool=b.dataset.buildTool;document.querySelectorAll('[data-build-tool]').forEach(x=>x.classList.toggle('active',x===b))});
$('wallHeight').oninput=e=>{wallHeightCm=+e.target.value;$('wallHeightLabel').textContent=wallHeightCm+'cm';localStorage.setItem('madori-wall-height',wallHeightCm);drawBuilder()};$('rotateBuilderLeft').onclick=()=>{buildRotation=(buildRotation+3)%4;drawBuilder()};$('rotateBuilderRight').onclick=()=>{buildRotation=(buildRotation+1)%4;drawBuilder()};
$('roomsTo3dBtn').onclick=()=>{const rooms=items.filter(i=>i.type==='room');if(!rooms.length){toast('先に部屋を配置してください');return}checkpoint();const size=gridPx(),keys=new Set(floorTiles.map(t=>tileKey(t.x,t.y,t.size)));rooms.forEach(room=>{for(let y=Math.floor(room.y/size)*size;y<room.y+room.h;y+=size)for(let x=Math.floor(room.x/size)*size;x<room.x+room.w;x+=size){const key=tileKey(x,y,size);if(!keys.has(key)){floorTiles.push({x,y,size,color:room.color||floorColor,key});keys.add(key)}}});render();scheduleSave();resizeBuilder();toast('既存の部屋を3D化しました')};
wallHeightCm=+(localStorage.getItem('madori-wall-height')||240);$('wallHeight').value=wallHeightCm;$('wallHeightLabel').textContent=wallHeightCm+'cm';window.addEventListener('resize',()=>{if(!$('builder3dModal').classList.contains('hidden'))resizeBuilder()});
